    "passage": "新员工刚来公司时，经理并不要求他们马上完成所有任务。他先让经验丰富的员工带他们工作，再让他们独立完成简单的任务。每周经理都会和他们交流，了解他们遇到的困难，并根据实际情况调整培训计划。",
