    "passage": "一位负责人收到了两份销售报告。第一份显示某种商品的销售数量下降，第二份却显示客户对这种商品的需求正在增加。他进一步调查后发现，原来商店经常没有足够的商品可以卖。因此，单独看销售数据并不能完全了解客户的实际需求。",
