    "id": "r-change-3",
    "kind": "reading",
    "level": 5,
    "passage": "一家企业过去主要依靠一种产品获得收入。随着市场环境的变化，客户开始对新产品产生兴趣，原来的产品销售逐渐下降。企业负责人意识到，继续使用过去成功的方法并不一定能得到同样的结果。他决定在保持原有客户的同时，研究新的需求，并逐步开发新产品。",
