    "title": "Relationships: The unexpected gift",
    "passage": "他一直认为，为自己喜欢的人花更多的钱，就能让对方更快乐。到了她生日那天，他买了一件很贵的礼物，而她却告诉他，自己最想要的是和他一起休息一个下午。他这才明白，爱不一定要通过礼物来表达，有时认真地听对方说话就已经足够了。",
