    "title": "Business · The empty café 2: The experiment",
    "passage": "经理没有马上改变价格，而是选择了三种产品进行试验。他把制作每种产品所需的时间和材料记录下来，并向员工解释这样做的意义。起初，有些员工认为新的制度增加了工作压力，不愿意配合。经理没有批评他们，而是请他们参与设计新的工作方式。几天以后，员工发现工作反而比以前轻松了。与此同时，消费者等待的时间明显减少。经理意识到，解决成本问题不一定意味着降低服务质量。",
    "translation": "Rather than changing prices immediately, the manager tests three products and tracks time and materials. Staff initially dislike the new system, so he invites them to redesign the workflow. Work becomes easier and customers wait less. Cutting costs need not mean reducing service quality.",
