    "passageId": "r-science-attention",
    "passageLevel": 5,
    "title": "Science: Why interruptions feel so costly",
    "passage": "一位员工每天同时处理多个任务。他认为，自己能够在短时间内完成许多工作，因此常常在写报告时查看手机，或者突然开始处理另一个项目。可是到了晚上，他发现重要的任务并没有完成。第二天，他采用了不同的方式：在一定时间内只处理一个任务，结束后再看手机。虽然他感觉自己做的事情变少了，但实际完成的任务反而增加了。这个例子说明，不断改变注意的对象可能使我们难以集中精神。",
    "translation": "An employee switches among tasks and phones but finishes little. The next day he works on one task at a time and checks his phone afterward. He feels less busy but gets more done. This fictional example illustrates the cost of switching attention.",
