    "title": "Science: Too many choices",
    "passage": "一家商店希望为消费者提供更多选择，于是增加了产品的种类。经理认为，这样一定能够满足更多人的需求。但一段时间后，他发现顾客在店里停留的时间变长了，实际购买的数量却没有提高。有些顾客比较了很多产品，最后什么也没有买。经理于是组织员工开展一次试验：保留不同价格的代表性产品，并清楚地介绍每种产品的特点。顾客更容易确定自己的选择。这并不表示选择越少越好，而是说明选择的结构也很重要。",
