    "passage": "一个团队需要选择新的成员。负责这项工作的经理发现，自己对第一位参加面试的人有很好的印象，因为那个人表达得非常清楚。随后，他阅读了其他人的资料，却总是更加关注第一位的优势。另一位员工提醒他，良好的表达能力与实际工作水平不一定相同。于是，团队确定了统一的评价方式，分别记录每个人完成任务的情况。最终，他们选择的人不是最初给经理留下最好印象的人。这个过程让经理重新认识了自己的判断。",
