    "title": "Mystery · Room 305 1: The wrong message",
    "passage": "一位记者到外地参加活动，住进了一家酒店。晚上，他收到一条没有名字的信息，内容很简单：“请不要把房间里的书交给任何人。”记者检查了房间，果然在桌子下面发现了一本书。书里记录着许多人的名字和日期，但没有说明这些记录的意义。记者认为信息可能发错了，于是联系了酒店的工作人员。工作人员告诉他，原来准备住这个房间的人临时改变了计划。记者决定把书交给酒店保管，并请工作人员联系原来的客人。",
    "translation": "A journalist at a hotel receives an anonymous message about a book in the room. He finds one with names and dates. Hotel staff explain another guest changed plans. He hands the book to staff for safekeeping and asks them to contact that guest.",
