    "passageId": "r-culture-tea",
    "passageLevel": 5,
    "title": "Culture: A cup of tea with a stranger",
    "passage": "一位外国学生去中国朋友家做客。朋友的父亲准备了茶，并邀请他坐下来一起交流。学生原来以为喝茶只是为了解决口渴的问题，却发现主人并不急着喝，而是一边准备茶一边介绍自己家乡的生活。学生了解到，在这个家庭中，喝茶也是与朋友相处的一种方式。后来，他也邀请自己的朋友喝茶，不过并没有要求大家采用完全相同的方式。他认为，了解一种传统的意义比简单地重复它的形式更重要。",
    "translation": "An international student visits a Chinese friend's family. Preparing tea becomes an opportunity to talk about their hometown. In this family tea is a way of spending time together. The student values understanding a tradition rather than mechanically copying its form.",
