    "title": "Learning: Meeting a word again",
    "passage": "一个学生第一次阅读一篇文章时，遇到了一个不熟悉的词。他查看了词的意思，并继续阅读。第二天，他在另一篇文章里又遇到了同一个词，这次他不需要马上查看就能理解。几天以后，他尝试用这个词讲述自己的经历，发现自己虽然能够理解，却还不能自然地使用。老师提醒他，认识一个词和掌握一个词是不同程度的能力。因此，他开始在不同的情况中反复使用学过的词，而不只是记住它的意思。",
