    "passageLevel": 5,
    "title": "Learning: A plan that survived Monday",
    "passage": "一个学生为自己制定了非常详细的学习计划，每天要完成大量任务。然而到了第三天，他因为工作突然增加而无法按计划学习。他原来认为，只要有一天没有完成任务，整个计划就失去了意义。朋友建议他确定一个容易完成的基本目标，同时保留更高的目标作为选择。这样，即使遇到特殊情况，他也能够继续保持学习的习惯。几周以后，他发现自己的学习更加稳定，而且对学习的压力也减少了。",
    "translation": "A student designs a demanding plan but work interrupts it. A friend suggests a manageable minimum plus an optional higher target. He maintains a stable habit even on difficult days and feels less pressure.",
