    "title": "Business · The empty café 1: A full room, no profit",
    "passage": "一家新开的咖啡店每天都有很多消费者，但是月底的收入却不够支付成本。老板以为只要扩大规模，就能提高利润，因此准备再开一家店。新来的经理分析了过去一个月的销售记录，发现最受欢迎的产品其实几乎没有利润。由于员工常常免费为顾客提供更多服务，工作时间也比原来预计的长。经理提出，先不要扩大经营规模，而要确定每种产品的实际成本。老板虽然不太同意，还是决定给他两周时间。",
    "translation": "A new café is busy, but monthly revenue barely covers costs. The owner wants to expand; the new manager examines records and finds that popular products earn almost no profit and extra services increase labour time. He suggests measuring real product costs before expanding. The owner gives him two weeks.",
