    "title": "Relationships: The appointment that went wrong",
    "passage": "他们约好周六下午见面。男朋友因为工作没有按时到，也忘了提前告诉她。她等了很久，以为他不重视这次见面。见面以后，他一直解释自己为什么这么忙，却没有问她有什么感觉。后来，他才明白，她生气不是因为他工作，而是因为她一直不知道发生了什么。于是他们商量，以后如果不能按时到，就提前告诉对方。",
