    "passageLevel": 5,
    "title": "Travel: A conversation at the market",
    "passage": "一位游客在当地市场看到一种从来没有吃过的水果。他想知道应该怎么吃，于是用中文向卖水果的人请教。开始时，他没有听清楚对方说的话，只好请对方说慢一点。卖水果的人没有觉得麻烦，而是拿出一个水果，一边做一边解释。游客发现，自己虽然认识不少汉字，但真正交流时还需要学会根据情况理解别人的意思。这次经历使他更愿意主动与当地人说话。",
    "translation": "A visitor asks a seller how to eat an unfamiliar fruit. When he cannot understand, he asks the seller to slow down. The seller demonstrates. The visitor learns that communication needs context as well as characters.",
