    "passageId": "r-health-sleep",
    "passageLevel": 5,
    "title": "Science: The evening routine",
    "passage": "一位学生准备参加考试，觉得每天的时间不够用，因此常常学习到很晚才睡。虽然他学习的时间增加了，但第二天白天上课时却很难集中注意力。他的朋友建议他先安排好每天的学习计划，并保证有足够的时间休息。他试了一个星期，发现自己在白天学习时感觉好多了，也能够更清楚地记住学过的内容。这个故事提醒我们，学习的效果不只与学习时间有关。",
    "translation": "A student studies late and has trouble concentrating the next day. A friend suggests planning and allowing enough rest. After a week he feels better and remembers more clearly. Study effectiveness is not just about hours spent.",
