    "title": "Everyday life: The phone left at home",
    "passage": "今天早上，他出门以后才发现手机没有带。开始的时候，他很不习惯，因为平时坐车时总是在看手机。可是到了车站，他注意到附近开了一家小店，还见到了一位老朋友。两人一起走了一段路，说了很多过去的事情。晚上回家时，他觉得今天过得不错。他决定以后坐车时少看手机，多看看身边的人和事。",
