    "passageId": "r-health-walk",
    "passageLevel": 4,
    "title": "Science: A walk after work",
    "passage": "一位上班的人每天坐在办公室里，回家以后只想休息。他知道运动对健康有好处，却总觉得没有时间。有一天，他决定不再给自己安排很难完成的计划，而是每天晚饭以后和朋友一起走一会儿。开始的时候，他有时也想放弃，但是因为朋友每天都在等他，他慢慢习惯了这样的生活。几个月以后，运动已经成为他生活的一部分。",
    "translation": "An office worker knows exercise is good but feels too busy. He starts with a short daily walk with a friend rather than an ambitious plan. Social support helps the habit become part of his life.",
