    "title": "Everyday life: A lost wallet",
    "passage": "一个学生放学后坐车回家。到家以后，他才发现自己的包里没有钱包。他想起今天在学校门口买过水，就给那家小店打了电话。店里的人告诉他，有人看到一个钱包放在桌子上，就拿到店里了。学生马上回到小店，发现里面的钱和卡都还在。他非常高兴，想给店里的人一些钱，但是店里的人说不用了。",
