    "passage": "一位学生在网络上看到一篇报道，称某种新的学习方式能够迅速提高成绩。他很感兴趣，但没有马上相信报道里的结论，而是先查看相关研究的内容。他发现，参加研究的人数很少，而且研究只进行了很短的时间。虽然结果值得关注，但并不能说明这种方式一定适合所有人。学生决定自己进行简单的试验，并继续观察其他研究的结果。他认为，在接受一个新观点以前，应该先了解支持它的材料是否充分。",
