    "title": "Business: The route that saved time",
    "passage": "一家企业每天需要把产品送到不同地区的客户手中。过去，工作人员主要根据自己的经验安排运输顺序。有时两辆车会在相同的地区工作，而另一个地区的客户却需要等很久。为了改善这种情况，企业开始收集有关客户位置和服务时间的数据，并利用系统设计运输方案。经过试验，工作人员发现，不仅运输时间减少了，而且客户也更容易在约定的时间收到产品。不过，遇到特殊情况时，仍然需要人员根据实际情况进行调整。",
    "translation": "A company plans deliveries by experience, sometimes sending two vehicles to the same area while others wait. It collects location and time data and tests route plans. Delivery time decreases and punctuality improves, though people still adjust for exceptions.",
