    "passageLevel": 5,
    "title": "Science: The cup of hot water",
    "passage": "一位学生想了解不同材料对水的温度有什么影响。他准备了两种不同材料的杯子，分别倒入同样数量、同样温度的热水，并将它们放在同一个地方。每隔一段时间，他就记录一次水的温度。朋友建议再换一个房间进行试验，但学生认为，如果同时改变太多条件，就很难确定是什么因素造成了结果的不同。因此，他先完成这次试验，再考虑其他条件的影响。",
    "translation": "A student compares cups made of different materials using the same quantity and temperature of water. He measures temperatures over time. He avoids changing the room at the same time because that would make it harder to isolate the cause.",
