    "passageLevel": 5,
    "title": "Relationships: Saying no with care",
    "passage": "一个人总是答应朋友提出的各种要求，即使自己已经有其他安排，也很少拒绝。时间长了，他发现自己的工作和休息都受到了影响，而且有时会因为朋友的要求感到不满。另一位朋友建议他，在回答之前先考虑自己的实际情况。如果不能提供帮助，可以清楚地说明原因，并在可能的情况下提出其他方式。开始时他担心这样会影响关系，但结果与他的想法不同。有些朋友反而更理解他的情况，也开始更加尊重他的安排。",
