    "id": "r-tech-payment-2",
    "kind": "reading",
    "level": 5,
    "passageId": "r-tech-payment",
    "passageLevel": 5,
    "title": "Business: When the network stops",
    "passage": "一家小店采用新的系统以后，大部分工作都通过网络完成。有一天，网络突然出现问题，员工无法查看客户的订单，工作几乎完全停止。经理发现，新的技术虽然提高了效率，但企业没有为特殊情况准备其他方案。他组织人员讨论，决定每天保存必要的记录，并制定网络出现问题时的基本工作方式。后来，类似的情况再次发生，员工能够继续完成主要任务。经理认为，采用技术时，不仅要考虑正常情况下的效率，也要考虑系统无法使用时的风险。",
    "translation": "A shop relies on an online system. An outage prevents staff from seeing orders. Management creates a fallback process and saves essential records. Another outage no longer stops the main tasks. Resilience matters alongside efficiency.",
