    "title": "Science: A map is not the world",
    "passage": "一位老师在课堂上给学生看了两张地图。第一张地图主要显示城市之间的距离，而另一张地图主要显示坐车需要的时间。学生发现，同样的两个城市在不同地图上的关系看起来很不一样。老师解释，地图只是根据某个目的选择并表达部分信息的工具，并不是现实世界本身。类似的情况也存在于统计数据中。我们在使用一份资料以前，应该先明确它能回答什么问题，以及它没有提供的信息。",
