    "passageLevel": 5,
    "title": "Mystery · The door 3: The forgotten friendship",
    "passage": "年轻人把照片带回家，请父亲看一看。父亲看完以后很久没有说话。他告诉儿子，自己过去就住在那个地区，与照片里的其他人一起工作。后来因为生活发生变化，他们渐渐失去了联系。父亲原来以为再也没有机会见到这些朋友，所以收到这个消息十分感动。到了活动那一天，年轻人与父亲一起回到那个地方。父亲不仅见到了多年没有见的朋友，还认识了他们的孩子。那几封奇怪的信，最终帮助许多人重新建立了联系。",
    "translation": "The young man shows the photo to his father, who recognises former colleagues. They lost contact over the years. At the event, father and son meet old friends and their children. The odd letters restore connections.",
