    "passageLevel": 5,
    "title": "Business · The empty café 3: A better decision",
    "passage": "两周后，经理把统计结果交给老板。虽然总收入没有明显增长，但由于浪费减少，利润有了很大的改善。老板原来关注的是每天来了多少顾客，而经理关注的是每次交易能为企业带来多少价值。双方经过讨论，确定未来的发展方案：先继续改善现有的经营模式，等利润稳定以后再考虑新的项目。老板说，以前他只看到了表面的成功，现在才明白，真正的优势来自持续改善，而不是简单地扩大规模。",
    "translation": "After two weeks, revenue is similar but profit improves as waste falls. The owner and manager agree to improve the current model before opening another shop. The owner realises sustained improvement matters more than superficial growth.",
