    "title": "Business · The fruit shop 1: An expensive mistake",
    "passage": "一家水果店的老板发现，周末的需求比平时高得多。为了避免缺少商品，他每次都根据最高的销售量准备商品。然而，遇到天气不好的周末，销售量就会下降，许多水果只能低价出售。员工建议按照平均销售量准备，老板却担心这样会失去重要的消费者。两个人的意见完全不同。一位朋友提醒他们，真正的问题不是应该准备多少，而是如何在减少损失和满足需求之间取得平衡。",
    "translation": "A fruit shop stocks according to peak weekend sales, but poor weather leaves unsold fruit. An employee suggests the average; the owner fears shortages. A friend points out the need to balance waste and demand.",
