    "passageLevel": 5,
    "title": "Business · The fruit shop 2: Learning from data",
    "passage": "老板开始分别记录每天的天气、销售量以及剩下的商品数量。经过一个月的观察，他发现不同类型的消费者具有不同的购买习惯：附近的居民通常在下午来，而餐厅主要在上午购买水果。于是，他采用了新的方法，根据不同时间的需求安排商品。对于容易出现损失的水果，他减少一次购买的数量，同时增加购买的次数。虽然运输成本有所提高，但是总损失下降了。老板终于明白，数据的意义在于帮助人们采取合适的行动。",
    "translation": "The owner tracks weather, sales and leftovers. He discovers residents shop in the afternoon while restaurants buy in the morning. Smaller, more frequent purchases increase transport costs but reduce overall losses. Data helps people choose suitable actions.",
