    "title": "Mystery · The door 1: Three envelopes",
    "passage": "一位年轻人晚上回家时，发现门口放着三封信。第一封信只有一个地址，另一封信里有一张旧照片，最后一封信写着一句很奇怪的话：请在明天晚上七点来。他没有认出照片上的人，也不知道那个地址属于谁。他先联系了住在附近的朋友，朋友却说自己也收到过类似的信。两个人比较了信的内容，发现他们收到的地址完全一样。他们决定第二天一起去看看。",
