    "title": "Mystery · The door 2: A room full of photographs",
    "passage": "第二天晚上，两个人按时来到信上写的地址。那里是一家很小的商店，门已经开了。店里没有商品，而是放着许多过去的照片。一位老人正在整理这些照片，他看见两个年轻人以后，十分高兴。他告诉他们，自己正在准备一次关于这个地区历史的活动，希望过去住在这里的人能够参加。他通过朋友找到他们的地址，并把过去拍的照片寄给了他们。可是其中一张照片让年轻人十分意外，因为照片上的人长得很像他的父亲。",
    "translation": "The friends arrive at the address, a shop full of old photographs. An older man is organising a local history event and sent photos to former residents. One photo surprises the young man because someone resembles his father.",
