    "passageId": "r-rel-listen",
    "passageLevel": 5,
    "title": "Relationships: Advice or understanding?",
    "passage": "一位朋友在工作中遇到了困难，回家以后向自己的爱人讲述当天的经历。对方一听完就开始提出各种解决方案，但朋友的心情反而变得更差了。爱人觉得奇怪，因为他认为自己在帮助对方。经过进一步交流，他才发现，朋友此时真正需要的不是建议，而是有人愿意听她说话，并理解她的感受。以后遇到类似的情况，他会先问对方需要什么帮助。双方的沟通逐渐变得更加顺利。",
    "translation": "Someone shares a difficult day with a partner. The partner immediately proposes solutions, making her feel worse. He realises she wanted to be heard, not advised. Later he asks what support she wants before offering suggestions.",
