    "passageId": "r-rel-distance",
    "passageLevel": 5,
    "title": "Relationships: Two cities, one plan",
    "passage": "一对年轻人因为工作分别住在不同的城市。开始时，他们认为每天只要有机会就联系对方，并不需要确定具体时间。可是由于双方的工作安排经常发生变化，他们有时连续几天没有好好交流。经过讨论，两个人决定每周保留几个共同的时间。如果一方临时有事，就提前通知另一方，而不是让对方一直等待。这样做并没有限制他们的自由，反而让双方都更加安心。他们逐渐明白，稳定的联系需要共同努力。",
    "translation": "A couple lives in separate cities for work. Unplanned contact leads to several days without a real conversation. They agree on shared times and notify each other of changes. Predictability makes them feel more secure without removing freedom.",
