    "title": "Travel: The longer road",
    "passage": "两个朋友第一次来到一个城市。他们准备去参观一座有名的建筑，地图上显示有两条路。一条路比较短，但要经过一个正在修路的地方；另一条路虽然比较长，却可以坐车直接到达。一个人坚持走短路，认为这样一定能节省时间。结果他们走了很久才发现前面的路不能通过。最后他们不得不回到原来的地方。两个人都明白了，距离短不一定表示用的时间少。",
